        return titleOrder !== 0 ? titleOrder : left.movie.id - right.movie.id;
    }

    function addToTopCandidates(topCandidates, candidate, limit) {
        const insertionIndex = topCandidates.findIndex(
            (existingCandidate) => compareCandidates(candidate, existingCandidate) < 0
        );

        if (insertionIndex === -1) {
            if (topCandidates.length < limit) {
                topCandidates.push(candidate);
            }
            return;
        }

        topCandidates.splice(insertionIndex, 0, candidate);
        if (topCandidates.length > limit) {
            topCandidates.pop();
        }
    }

    function rankRecommendations(movies, ratingSummary, likedMovieId, requestedLimit) {
        const movieId = Number(likedMovieId);
        const likedMovie = movies.find((movie) => movie.id === movieId);
        if (!likedMovie) {
            throw new Error(`Movie ID ${likedMovieId} was not found.`);
        }

        const parsedLimit = Number(requestedLimit);
        const limit = Number.isInteger(parsedLimit) && parsedLimit > 0
            ? Math.min(parsedLimit, 20)
            : 2;
        const topCandidates = [];

        movies.forEach((candidateMovie) => {
            if (candidateMovie.id === likedMovie.id) {
                return;
            }

            const similarity = jaccardFromMasks(likedMovie.genreMask, candidateMovie.genreMask);
            if (similarity <= 0) {
                return;
            }

            const candidate = {
                movie: candidateMovie,
                similarity,
                sharedGenres: Object.freeze(
                    likedMovie.genres.filter((genre) => candidateMovie.genres.includes(genre))
                ),
                rating: ratingFor(ratingSummary, candidateMovie.id)
            };
            addToTopCandidates(topCandidates, candidate, limit);
        });

        return Object.freeze(topCandidates);
    }

    function elements() {
        return {
            panel: document.getElementById("recommender-panel"),
            form: document.getElementById("recommender-form"),
            movieSelect: document.getElementById("movie-select"),
            resultCount: document.getElementById("result-count"),
            recommendButton: document.getElementById("recommend-button"),
            retryButton: document.getElementById("retry-button"),
            status: document.getElementById("result"),
            resultsHeading: document.getElementById("results-heading"),
            recommendationList: document.getElementById("recommendation-list")
        };
    }

    function setStatus(statusElement, message, kind) {
        statusElement.textContent = message;
        statusElement.className = `status status--${kind}`;
    }

    function clearRecommendations(ui) {
        ui.recommendationList.replaceChildren();
        ui.resultsHeading.hidden = true;
    }

    function setControlsEnabled(ui, enabled) {
        ui.movieSelect.disabled = !enabled;
        ui.resultCount.disabled = !enabled;
        ui.recommendButton.disabled = !enabled;
    }

    function populateMovieSelect(selectElement, movies) {
        const placeholder = document.createElement("option");
        placeholder.value = "";
        placeholder.textContent = "Select a movie";
        selectElement.replaceChildren(placeholder);

        const sortedMovies = [...movies].sort((left, right) => {
            const titleOrder = titleCollator.compare(left.title, right.title);
            return titleOrder !== 0 ? titleOrder : left.id - right.id;
        });

        const fragment = document.createDocumentFragment();
        sortedMovies.forEach((movie) => {
            const option = document.createElement("option");
            option.value = String(movie.id);
            option.textContent = movie.title;
            fragment.appendChild(option);
        });
        selectElement.appendChild(fragment);
    }

    function createRecommendationCard(recommendation, index) {
        const item = document.createElement("li");
        item.className = "recommendation-card";

        const rank = document.createElement("span");
        rank.className = "rank";
        rank.setAttribute("aria-label", `Rank ${index + 1}`);
        rank.textContent = String(index + 1);

        const details = document.createElement("div");
        const title = document.createElement("h3");
        title.className = "movie-title";
        title.textContent = recommendation.movie.title;

        const reason = document.createElement("p");
        reason.className = "movie-reason";
        reason.textContent = `Shared ${recommendation.sharedGenres.join(", ")}`;

        const rating = document.createElement("p");
        rating.className = "movie-rating";
        if (recommendation.rating) {
            const ratingWord = recommendation.rating.count === 1 ? "rating" : "ratings";
            rating.textContent = `${recommendation.rating.average.toFixed(1)}/5 from ${recommendation.rating.count} ${ratingWord}`;
        } else {
            rating.textContent = "Rating data unavailable";
        }

        const score = document.createElement("span");
        score.className = "score";
        score.textContent = `${Math.round(recommendation.similarity * 100)}% match`;

        details.append(title, reason, rating);
        item.append(rank, details, score);
        return item;
    }

    function renderRecommendations(ui, likedMovie, recommendations) {
        clearRecommendations(ui);

        if (recommendations.length === 0) {
            setStatus(
                ui.status,
                `No movies share a genre with “${likedMovie.title}”. Try another film.`,
                "warning"
            );
            return;
        }

        const fragment = document.createDocumentFragment();
        recommendations.forEach((recommendation, index) => {
            fragment.appendChild(createRecommendationCard(recommendation, index));
        });

        ui.recommendationList.appendChild(fragment);
        ui.resultsHeading.hidden = false;
        const movieWord = recommendations.length === 1 ? "movie" : "movies";
        setStatus(
            ui.status,
            `Found ${recommendations.length} similar ${movieWord} for “${likedMovie.title}”.`,
            "success"
        );
    }

    function recommend(event) {
        event.preventDefault();
        const ui = elements();
        const selectedMovieId = Number(ui.movieSelect.value);

        if (!Number.isInteger(selectedMovieId) || !state.movieById.has(selectedMovieId)) {
            clearRecommendations(ui);
            setStatus(ui.status, "Select a movie before requesting recommendations.", "error");
            ui.movieSelect.focus();
            return;
        }

        ui.recommendButton.disabled = true;
        try {
            const likedMovie = state.movieById.get(selectedMovieId);
            const recommendations = rankRecommendations(
                state.movies,
                state.ratingSummary,
                selectedMovieId,
                Number(ui.resultCount.value)
            );
            renderRecommendations(ui, likedMovie, recommendations);
        } catch (error) {
            clearRecommendations(ui);
            setStatus(ui.status, `Recommendations could not be calculated: ${error.message}`, "error");
        } finally {
            ui.recommendButton.disabled = false;
        }
    }

    async function initialize() {
        if (state.loading) {
            return;
        }

        const ui = elements();
        state.loading = true;
        ui.panel.setAttribute("aria-busy", "true");
        ui.retryButton.hidden = true;
        clearRecommendations(ui);
        setControlsEnabled(ui, false);
        setStatus(ui.status, "Loading movie data…", "loading");

        try {
            if (!global.MovieData) {
                throw new Error("The data module did not load.");
            }

            const dataset = await global.MovieData.loadData();
            state.movies = dataset.movies;
            state.movieById = new Map(dataset.movies.map((movie) => [movie.id, movie]));
            state.ratingSummary = dataset.ratingSummary;

            populateMovieSelect(ui.movieSelect, dataset.movies);
            setControlsEnabled(ui, true);

            if (dataset.warnings.length > 0) {
                setStatus(
                    ui.status,
                    `Loaded ${dataset.movies.length.toLocaleString()} movies. ${dataset.warnings.join(" ")}`,
                    "warning"
                );
            } else {
                setStatus(
                    ui.status,
                    `Loaded ${dataset.movies.length.toLocaleString()} movies and ${dataset.ratingSummary.totalRatings.toLocaleString()} ratings. Choose a movie to begin.`,
                    "success"
                );
            }
        } catch (error) {
            setStatus(
                ui.status,
                `Movie data could not be loaded: ${error.message} Run this app through a local web server and try again.`,
                "error"
            );
            ui.retryButton.hidden = false;
        } finally {
            state.loading = false;
            ui.panel.setAttribute("aria-busy", "false");
        }
    }

    global.MovieRecommenderCore = Object.freeze({
        jaccardSimilarity,
        rankRecommendations
    });

    document.addEventListener("DOMContentLoaded", () => {
        const ui = elements();
        ui.form.addEventListener("submit", recommend);
        ui.retryButton.addEventListener("click", initialize);
        initialize();
    });
}(window, document));

:root {
    color-scheme: light;
    --page: #eef3f8;
    --surface: #ffffff;
    --surface-muted: #f5f8fb;
    --text: #162233;
    --text-muted: #536274;
    --border: #cbd6e2;
    --accent: #1769aa;
    --accent-hover: #0e548d;
    --accent-soft: #e4f1fb;
    --success: #146c43;
    --success-soft: #e8f6ee;
    --warning: #76530b;
    --warning-soft: #fff5d7;
    --error: #a61b1b;
    --error-soft: #fdecec;
    --shadow: 0 18px 48px rgba(30, 55, 82, 0.12);
    --radius-lg: 22px;
    --radius-md: 12px;
}

* {
    box-sizing: border-box;
}

body {
    min-width: 320px;
    min-height: 100vh;
    margin: 0;
    padding: clamp(24px, 6vw, 72px) 20px;
    background: linear-gradient(145deg, #f8fafc 0%, var(--page) 55%, #e8f0f7 100%);
    color: var(--text);
    font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    line-height: 1.5;
}

button,
select {
    font: inherit;
}

.app-shell {
    width: min(880px, 100%);
    margin: 0 auto;
}

.intro {
    max-width: 690px;
    margin-bottom: 28px;
}

.eyebrow {
    margin: 0 0 8px;
    color: var(--accent);
    font-size: 0.78rem;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
}

h1 {
    margin: 0;
    font-size: clamp(2rem, 6vw, 3.7rem);
    line-height: 1.05;
    letter-spacing: -0.045em;
}

.intro-copy {
    max-width: 650px;
    margin: 18px 0 0;
    color: var(--text-muted);
    font-size: clamp(1rem, 2vw, 1.12rem);
}

.panel {
    padding: clamp(20px, 5vw, 40px);
    background: var(--surface);
    border: 1px solid rgba(203, 214, 226, 0.85);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow);
}

.controls {
    display: grid;
    grid-template-columns: minmax(0, 1fr) 140px auto;
    gap: 16px;
    align-items: end;
}

.field {
    display: grid;
    gap: 7px;
}

label {
    font-size: 0.88rem;
    font-weight: 750;
}

select {
    width: 100%;
    min-height: 48px;
    padding: 10px 38px 10px 12px;
    color: var(--text);
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    cursor: pointer;
}

select:hover:not(:disabled) {
    border-color: #8ba4bb;
}

button {
    min-height: 48px;
    padding: 11px 18px;
    border: 0;
    border-radius: 10px;
    font-weight: 750;
    cursor: pointer;
}

#recommend-button {
    color: #ffffff;
    background: var(--accent);
}

#recommend-button:hover:not(:disabled) {
    background: var(--accent-hover);
}

button:disabled,
select:disabled {
    cursor: not-allowed;
    opacity: 0.58;
}

button:focus-visible,
select:focus-visible,
a:focus-visible {
    outline: 3px solid #f2a900;
    outline-offset: 3px;
}

.feedback-row {
    display: flex;
    gap: 14px;
    align-items: center;
    margin-top: 22px;
}

.status {
    flex: 1;
    margin: 0;
    padding: 13px 15px;
    border-left: 4px solid var(--accent);
    border-radius: 8px;
    background: var(--accent-soft);
    color: #174d77;
    font-weight: 650;
}

.status--loading {
    font-style: italic;
}

.status--success {
    border-left-color: var(--success);
    background: var(--success-soft);
    color: var(--success);
}

.status--warning {
    border-left-color: var(--warning);
    background: var(--warning-soft);
    color: var(--warning);
}

.status--error {
    border-left-color: var(--error);
    background: var(--error-soft);
    color: var(--error);
}

.retry-button {
    color: var(--accent);
    background: var(--accent-soft);
}

.retry-button:hover {
    background: #d3e8f8;
}

.results h2 {
    margin: 32px 0 14px;
    font-size: 1.15rem;
}

.recommendation-list {
    display: grid;
    gap: 12px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.recommendation-card {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 14px;
    align-items: center;
    padding: 17px;
    background: var(--surface-muted);
    border: 1px solid #dce5ed;
    border-radius: var(--radius-md);
}

.rank {
    display: grid;
    width: 34px;
    height: 34px;
    place-items: center;
    color: var(--accent);
    background: var(--accent-soft);
    border-radius: 50%;
    font-weight: 800;
}

.movie-title {
    margin: 0 0 4px;
    font-size: 1rem;
}

.movie-reason,
.movie-rating {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.88rem;
}

.score {
    min-width: 72px;
    color: var(--accent);
    font-size: 0.92rem;
    font-weight: 800;
    text-align: right;
}

footer {
    max-width: 700px;
    margin: 20px auto 0;
    color: var(--text-muted);
    font-size: 0.82rem;
    text-align: center;
}

footer p {
    margin: 0;
}

a {
    color: var(--accent-hover);
}

[hidden] {
    display: none !important;
}

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

@media (max-width: 720px) {
    .controls {
        grid-template-columns: minmax(0, 1fr) 120px;
    }

    .field--movie,
    #recommend-button {
        grid-column: 1 / -1;
    }

    .field--count {
        grid-column: 1 / 2;
    }

    #recommend-button {
        width: 100%;
    }
}

@media (max-width: 520px) {
    body {
        padding-inline: 12px;
    }

    .controls {
        grid-template-columns: 1fr;
    }

    .field--movie,
    .field--count,
    #recommend-button {
        grid-column: 1;
    }

    .feedback-row {
        align-items: stretch;
        flex-direction: column;
    }

    .recommendation-card {
        grid-template-columns: auto minmax(0, 1fr);
    }

    .score {
        grid-column: 2;
        text-align: left;
    }
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
    }
}

