ObjC.import("Foundation");

function readText(path) {
    const contents = $.NSString.stringWithContentsOfFileEncodingError(
        path,
        $.NSUTF8StringEncoding,
        null
    );
    if (!contents) {
        throw new Error(`Could not read ${path}`);
    }
    return ObjC.unwrap(contents);
}

function assert(condition, message) {
    if (!condition) {
        throw new Error(message);
    }
}

function assertEqual(actual, expected, message) {
    if (actual !== expected) {
        throw new Error(`${message}: expected ${expected}, received ${actual}`);
    }
}

function assertClose(actual, expected, tolerance, message) {
    if (Math.abs(actual - expected) > tolerance) {
        throw new Error(`${message}: expected ${expected}, received ${actual}`);
    }
}

function assertArrayEqual(actual, expected, message) {
    assertEqual(JSON.stringify(actual), JSON.stringify(expected), message);
}

function assertThrows(callback, expectedText, message) {
    let thrown = null;
    try {
        callback();
    } catch (error) {
        thrown = error;
    }
    assert(thrown, `${message}: expected an exception`);
    assert(
        String(thrown.message).includes(expectedText),
        `${message}: exception did not include “${expectedText}”`
    );
}

function run(arguments) {
    const projectRoot = arguments[0];
    if (!projectRoot) {
        throw new Error("Project root argument is required.");
    }

    const window = {};
    const document = {
        addEventListener() {}
    };

    eval(readText(`${projectRoot}/data.js`));
    eval(readText(`${projectRoot}/script.js`));

    const itemText = readText(`${projectRoot}/u.item`);
    const ratingText = readText(`${projectRoot}/u.data`);
    const movies = window.MovieData.parseItemData(itemText);

    assertEqual(movies.length, 1682, "Movie count");
    assertEqual(window.MovieData.GENRE_NAMES.length, 19, "Genre-name count");
    assertEqual(new Set(movies.map((movie) => movie.id)).size, 1682, "Unique movie IDs");

    const toyStory = movies.find((movie) => movie.id === 1);
    assertArrayEqual(
        toyStory.genres,
        ["Animation", "Children's", "Comedy"],
        "Toy Story genre mapping"
    );

    const unknownMovie = movies.find((movie) => movie.id === 267);
    assertArrayEqual(unknownMovie.genres, ["Unknown"], "Unknown genre mapping");

    const western = movies.find((movie) => movie.id === 203);
    assertArrayEqual(western.genres, ["Western"], "Western genre mapping");

    const ratingSummary = window.MovieData.parseRatingStats(
        ratingText,
        new Set(movies.map((movie) => movie.id))
    );
    assertEqual(ratingSummary.totalRatings, 100000, "Rating count");
    assertClose(ratingSummary.globalAverage, 3.52986, 0.000001, "Global rating average");
    assertEqual(ratingSummary.get(1).count, 452, "Toy Story rating count");
    assertClose(ratingSummary.get(1).average, 3.878318584071, 0.000000000001, "Toy Story average");

    const firstDataset = window.MovieData.createDataset(itemText, ratingText);
    const secondDataset = window.MovieData.createDataset(itemText, ratingText);
    assertEqual(firstDataset.movies.length, 1682, "First repeat-safe parse");
    assertEqual(secondDataset.movies.length, 1682, "Second repeat-safe parse");
    assert(firstDataset.movies !== secondDataset.movies, "Repeat parsing must produce isolated arrays");
    assertEqual(firstDataset.warnings.length, 0, "Valid ratings warning count");

    const fallbackDataset = window.MovieData.createDataset(itemText, "invalid rating row");
    assertEqual(fallbackDataset.movies.length, 1682, "Movie fallback after invalid ratings");
    assertEqual(fallbackDataset.ratingSummary.totalRatings, 0, "Invalid ratings must be discarded");
    assertEqual(fallbackDataset.warnings.length, 1, "Invalid ratings warning count");

    assertThrows(
        () => window.MovieData.parseItemData("1|Too few fields"),
        "expected 24",
        "Malformed movie rows"
    );
    assertThrows(
        () => window.MovieData.parseRatingStats("1\t1\t9\t123"),
        "between 1 and 5",
        "Out-of-range ratings"
    );

    const core = window.MovieRecommenderCore;
    assertClose(core.jaccardSimilarity(["Action"], ["Action"]), 1, 0, "Identical Jaccard");
    assertClose(core.jaccardSimilarity(["Action"], ["Comedy"]), 0, 0, "Disjoint Jaccard");
    assertClose(
        core.jaccardSimilarity(["Action", "Drama"], ["Action", "Comedy"]),
        1 / 3,
        0.000000000001,
        "Partial Jaccard"
    );
    assertClose(core.jaccardSimilarity([], []), 0, 0, "Empty-set Jaccard");

    const fixtures = [
        Object.freeze({ id: 1, title: "Liked", genres: Object.freeze(["Action"]), genreMask: 2 }),
        Object.freeze({ id: 2, title: "No overlap", genres: Object.freeze(["Comedy"]), genreMask: 32 }),
        Object.freeze({ id: 3, title: "Lower quality", genres: Object.freeze(["Action"]), genreMask: 2 }),
        Object.freeze({ id: 4, title: "Higher quality", genres: Object.freeze(["Action"]), genreMask: 2 })
    ];
    const fixtureRatings = {
        get(movieId) {
            if (movieId === 3) {
                return { count: 100, average: 2, qualityScore: 2.5 };
            }
            if (movieId === 4) {
                return { count: 10, average: 5, qualityScore: 4.2 };
            }
            return null;
        }
    };
    const ranked = core.rankRecommendations(fixtures, fixtureRatings, 1, 10);
    assertArrayEqual(ranked.map((entry) => entry.movie.id), [4, 3], "Quality-aware tie order");
    assert(!ranked.some((entry) => entry.movie.id === 2), "Zero-similarity movies must be excluded");
    assert(!ranked.some((entry) => entry.movie.id === 1), "Selected movie must be excluded");

    const titleTieFixtures = [
        fixtures[0],
        Object.freeze({ id: 5, title: "Zulu", genres: Object.freeze(["Action"]), genreMask: 2 }),
        Object.freeze({ id: 6, title: "Alpha", genres: Object.freeze(["Action"]), genreMask: 2 })
    ];
    const titleRanked = core.rankRecommendations(titleTieFixtures, null, 1, 1);
    assertEqual(titleRanked.length, 1, "Requested top-k limit");
    assertEqual(titleRanked[0].movie.id, 6, "Deterministic title tie-breaker");

    console.log("JavaScript tests: 28 assertions passed.");
    return "OK";
}

