:root {
    color-scheme: light;
    --page: #eef3f8;
    --surface: #ffffff;
    --surface-muted: #f5f8fb;
    --text: #162233;
    --text-muted: #536274;
    --border: #cbd6e2;
    --accent: #1769aa;
    --accent-hover: #0e548d;
    --accent-soft: #e4f1fb;
    --success: #146c43;
    --success-soft: #e8f6ee;
    --warning: #76530b;
    --warning-soft: #fff5d7;
    --error: #a61b1b;
    --error-soft: #fdecec;
    --shadow: 0 18px 48px rgba(30, 55, 82, 0.12);
    --radius-lg: 22px;
    --radius-md: 12px;
}

* {
    box-sizing: border-box;
}

body {
    min-width: 320px;
    min-height: 100vh;
    margin: 0;
    padding: clamp(24px, 6vw, 72px) 20px;
    background: linear-gradient(145deg, #f8fafc 0%, var(--page) 55%, #e8f0f7 100%);
    color: var(--text);
    font-family: Inter, ui-sans-serif, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
    line-height: 1.5;
}

button,
select {
    font: inherit;
}

.app-shell {
    width: min(880px, 100%);
    margin: 0 auto;
}

.intro {
    max-width: 690px;
    margin-bottom: 28px;
}

.eyebrow {
    margin: 0 0 8px;
    color: var(--accent);
    font-size: 0.78rem;
    font-weight: 800;
    letter-spacing: 0.14em;
    text-transform: uppercase;
}

h1 {
    margin: 0;
    font-size: clamp(2rem, 6vw, 3.7rem);
    line-height: 1.05;
    letter-spacing: -0.045em;
}

.intro-copy {
    max-width: 650px;
    margin: 18px 0 0;
    color: var(--text-muted);
    font-size: clamp(1rem, 2vw, 1.12rem);
}

.panel {
    padding: clamp(20px, 5vw, 40px);
    background: var(--surface);
    border: 1px solid rgba(203, 214, 226, 0.85);
    border-radius: var(--radius-lg);
    box-shadow: var(--shadow);
}

.controls {
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 16px;
    align-items: end;
}

.field {
    display: grid;
    gap: 7px;
}

label {
    font-size: 0.88rem;
    font-weight: 750;
}

select {
    width: 100%;
    min-height: 48px;
    padding: 10px 38px 10px 12px;
    color: var(--text);
    background-color: var(--surface);
    border: 1px solid var(--border);
    border-radius: 10px;
    cursor: pointer;
}

select:hover:not(:disabled) {
    border-color: #8ba4bb;
}

button {
    min-height: 48px;
    padding: 11px 18px;
    border: 0;
    border-radius: 10px;
    font-weight: 750;
    cursor: pointer;
}

#recommend-button {
    grid-column: 1 / -1;
    justify-self: start;
    color: #ffffff;
    background: var(--accent);
}

#recommend-button:hover:not(:disabled) {
    background: var(--accent-hover);
}

button:disabled,
select:disabled {
    cursor: not-allowed;
    opacity: 0.58;
}

button:focus-visible,
select:focus-visible,
a:focus-visible {
    outline: 3px solid #f2a900;
    outline-offset: 3px;
}

.feedback-row {
    display: flex;
    gap: 14px;
    align-items: center;
    margin-top: 22px;
}

.status {
    flex: 1;
    margin: 0;
    padding: 13px 15px;
    border-left: 4px solid var(--accent);
    border-radius: 8px;
    background: var(--accent-soft);
    color: #174d77;
    font-weight: 650;
}

.status--loading {
    font-style: italic;
}

.status--success {
    border-left-color: var(--success);
    background: var(--success-soft);
    color: var(--success);
}

.status--warning {
    border-left-color: var(--warning);
    background: var(--warning-soft);
    color: var(--warning);
}

.status--error {
    border-left-color: var(--error);
    background: var(--error-soft);
    color: var(--error);
}

.retry-button {
    color: var(--accent);
    background: var(--accent-soft);
}

.retry-button:hover {
    background: #d3e8f8;
}

.profile-summary {
    margin-top: 28px;
    padding: 18px;
    background: #f8f6ff;
    border: 1px solid #ddd7f2;
    border-radius: var(--radius-md);
}

.profile-summary h2,
.results h2 {
    margin: 0 0 8px;
    font-size: 1.15rem;
}

.profile-summary p {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.9rem;
}

.profile-genres {
    display: flex;
    flex-wrap: wrap;
    gap: 8px;
    margin: 14px 0 0;
    padding: 0;
    list-style: none;
}

.profile-genre {
    padding: 6px 10px;
    color: #493581;
    background: #ebe6fb;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 750;
}

.results h2 {
    margin: 32px 0 14px;
}

.recommendation-list {
    display: grid;
    gap: 12px;
    margin: 0;
    padding: 0;
    list-style: none;
}

.recommendation-card {
    display: grid;
    grid-template-columns: auto minmax(0, 1fr) auto;
    gap: 14px;
    align-items: center;
    padding: 17px;
    background: var(--surface-muted);
    border: 1px solid #dce5ed;
    border-radius: var(--radius-md);
}

.rank {
    display: grid;
    width: 34px;
    height: 34px;
    place-items: center;
    color: var(--accent);
    background: var(--accent-soft);
    border-radius: 50%;
    font-weight: 800;
}

.movie-title {
    margin: 0 0 4px;
    font-size: 1rem;
}

.movie-reason,
.movie-rating {
    margin: 0;
    color: var(--text-muted);
    font-size: 0.88rem;
}

.score {
    min-width: 72px;
    color: var(--accent);
    font-size: 0.92rem;
    font-weight: 800;
    text-align: right;
}

footer {
    max-width: 700px;
    margin: 20px auto 0;
    color: var(--text-muted);
    font-size: 0.82rem;
    text-align: center;
}

footer p {
    margin: 0;
}

a {
    color: var(--accent-hover);
}

[hidden] {
    display: none !important;
}

.visually-hidden {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border: 0;
}

@media (max-width: 720px) {
    .controls {
        grid-template-columns: 1fr;
    }

    #recommend-button {
        grid-column: 1;
        width: 100%;
    }
}

@media (max-width: 520px) {
    body {
        padding-inline: 12px;
    }

    .feedback-row {
        align-items: stretch;
        flex-direction: column;
    }

    .recommendation-card {
        grid-template-columns: auto minmax(0, 1fr);
    }

    .score {
        grid-column: 2;
        text-align: left;
    }
}

@media (prefers-reduced-motion: reduce) {
    *,
    *::before,
    *::after {
        scroll-behavior: auto !important;
        transition-duration: 0.01ms !important;
    }
}

