    <title>Content-Based Movie Recommender</title>
    <link rel="stylesheet" href="style.css">
</head>
<body>
    <div class="container" aria-busy="true">
        <h1>Content-Based Movie Recommender</h1>
        <p>Select three movies you like, and we'll find similar ones for you!</p>

        <div class="controls">
            <select id="watched-movie-1" class="movie-select" data-profile-movie aria-label="Watched movie 1" disabled>
                <option value="" disabled selected>Select watched movie 1</option>
            </select>
            <select id="watched-movie-2" class="movie-select" data-profile-movie aria-label="Watched movie 2" disabled>
                <option value="" disabled selected>Select watched movie 2</option>
            </select>
            <select id="watched-movie-3" class="movie-select" data-profile-movie aria-label="Watched movie 3" disabled>
                <option value="" disabled selected>Select watched movie 3</option>
            </select>
            <button id="recommend-btn" type="button" disabled>Get Recommendations</button>
        </div>

        <div id="result-box">
            <p id="result" class="loading" role="status" aria-live="polite">Please wait, loading data...</p>
        </div>
    </div>

    <script src="data.js"></script>
    <script src="script.js"></script>
</body>
</html>
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

body {
    font-family: 'Helvetica', 'Arial', sans-serif;
    background-color: #f4f7f6;
    color: #333;
    line-height: 1.6;
    padding: 20px;
    display: flex;
    justify-content: center;
    align-items: center;
    min-height: 100vh;
}

.container {
    background-color: white;
    border-radius: 10px;
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.1);
    padding: 30px;
    width: 90%;
    max-width: 600px;
}

h1 {
    text-align: center;
    margin-bottom: 15px;
    color: #2c3e50;
}

p {
    text-align: center;
    margin-bottom: 20px;
    color: #7f8c8d;
}

.controls {
    display: flex;
    flex-direction: column;
    gap: 15px;
    margin-bottom: 25px;
}

.movie-select {
    padding: 12px;
    border: 1px solid #ddd;
    border-radius: 5px;
    font-size: 16px;
    background-color: #f9f9f9;
    transition: border-color 0.3s;
}

.movie-select:focus {
    border-color: #3498db;
    outline: none;
}

#recommend-btn {
    padding: 12px 20px;
    background-color: #3498db;
    color: white;
    border: none;
    border-radius: 5px;
    font-size: 16px;
    cursor: pointer;
    transition: background-color 0.3s;
}

#recommend-btn:hover:not(:disabled) {
    background-color: #2980b9;
}

#recommend-btn:disabled,
.movie-select:disabled {
    cursor: not-allowed;
    opacity: 0.65;
}

#recommend-btn:focus-visible,
.movie-select:focus-visible {
    outline: 3px solid rgba(52, 152, 219, 0.35);
    outline-offset: 2px;
}

#result-box {
    background-color: #f8f9fa;
    padding: 20px;
    border-radius: 5px;
    border-left: 4px solid #3498db;
}

#result {
    font-weight: bold;
    color: #2c3e50;
    text-align: left;
    margin: 0;
}

#result.loading {
    color: #7f8c8d;
    font-style: italic;
}

#result.error {
    color: #e74c3c;
}

#result.warning {
    color: #9a6700;
}

#result.success {
    color: #27ae60;
}

@media (prefers-reduced-motion: reduce) {
    .movie-select,
    #recommend-btn {
        transition: none;
    }
}

