import AppKit
import Foundation
import PDFKit

let inputPath = CommandLine.arguments[1]
let outputDirectory = CommandLine.arguments[2]
let inputURL = URL(fileURLWithPath: inputPath)
let outputURL = URL(fileURLWithPath: outputDirectory, isDirectory: true)

guard let document = PDFDocument(url: inputURL) else {
    fatalError("Unable to open PDF")
}

print("PAGE_COUNT=\(document.pageCount)")

for pageIndex in 0..<document.pageCount {
    guard let page = document.page(at: pageIndex) else { continue }
    print("\n===== PAGE \(pageIndex + 1) =====")
    print(page.string ?? "")

    let bounds = page.bounds(for: .mediaBox)
    let width: CGFloat = 1400
    let height = width * bounds.height / bounds.width
    let thumbnail = page.thumbnail(of: NSSize(width: width, height: height), for: .mediaBox)
    guard
        let tiff = thumbnail.tiffRepresentation,
        let bitmap = NSBitmapImageRep(data: tiff),
        let png = bitmap.representation(using: .png, properties: [:])
    else {
        fatalError("Unable to render page \(pageIndex + 1)")
    }

    let pageURL = outputURL.appendingPathComponent("page-\(pageIndex + 1).png")
    try png.write(to: pageURL)
}

