        return {
            slots: entries.length,
            longTailSharePct: rounded(100 * entries.filter((entry) => !head.has(entry.movie.id)).length / entries.length, 1),
            uniqueItems: exposure.size,
            catalogCoveragePct: rounded(100 * exposure.size / movies.length, 1),
            medianRatingCount: median(counts),
            meanRatingCount: rounded(mean(counts), 1),
            top10ConcentrationPct: rounded(100 * topExposure.reduce((sum, value) => sum + value, 0) / entries.length, 1),
            meanNoveltyBits: rounded(mean(entries.map((entry) => Math.log2(100000 / ratingSummary.get(entry.movie.id).count))), 2),
            meanGenres: rounded(mean(entries.map((entry) => entry.movie.genreVector.reduce((sum, value) => sum + value, 0))), 2)
        };
    }

    const exampleIds = [1, 2, 3];
    const exampleMovies = exampleIds.map((movieId) => movieById.get(movieId));
    const exampleProfile = core.buildUserProfile(movies, exampleIds);
    const exampleItemProfile = {
        vector: movieById.get(1).genreVector,
        watchedMovieIds: exampleIds,
        watchedMovies: exampleMovies
    };
    const exampleItem = core.rankRecommendations(movies, ratingSummary, exampleItemProfile, 5);
    const exampleProfileTop = core.rankRecommendations(movies, ratingSummary, exampleProfile, 5);
    function exampleRows(list) {
        return list.map((entry) => ({
            title: entry.movie.title,
            score: rounded(entry.similarity, 3),
            ratings: entry.rating.count,
            segment: head.has(entry.movie.id) ? "Head" : "Long tail"
        }));
    }

    const output = {
        dataset: {
            movies: movies.length,
            ratings: ratingSummary.totalRatings,
            users: ratingsByUser.size,
            eligibleUsers: profileLists.length,
            globalAverage: rounded(ratingSummary.globalAverage, 5),
            headItems: head.size
        },
        example: {
            watched: exampleMovies.map((movie) => movie.title),
            itemTop5: exampleRows(exampleItem),
            profileTop5: exampleRows(exampleProfileTop)
        },
        cohort: {
            meanTop5Overlap: rounded(mean(overlaps), 2),
            overlapPct: rounded(100 * mean(overlaps) / 5, 1),
            item: metrics(itemLists),
            profile: metrics(profileLists),
            rawProfile: metrics(rawLists),
            profileMoreTailUsers: profileMoreTail,
            itemMoreTailUsers: itemMoreTail,
            equalTailUsers: equalTail
        }
    };
    console.log(JSON.stringify(output, null, 2));
    return "OK";
}

